"""Draft negotiation prose without allowing a model to choose a price or make numeric claims."""

from __future__ import annotations

import os
import re

import httpx

UNSAFE = re.compile(r"\d|(?:€|\bEUR\b|\bUSD\b|\b(?:BATNA|walk[- ]away|budget|target price)\b)", re.I)


class EmailWriter:
    def __init__(self):
        provider = os.getenv("LLM_PROVIDER", "openai-compatible").strip().lower()
        self.model = os.getenv("LLM_MODEL", "").strip()
        self.api_key = os.getenv("LLM_API_KEY", "").strip()
        self.base = os.getenv("LLM_BASE_URL", "https://api.openai.com/v1").rstrip("/")
        if provider not in {"openai", "openai-compatible"} or not self.api_key:
            self.model = ""

    @staticmethod
    def fallback(case, reply, has_packages):
        body = (reply or {}).get("body", "")
        lower = body.lower()
        if any(word in lower for word in ("capacity", "volume", "forecast", "allocation")):
            question = "What volume or forecast commitment would make a more competitive proposal workable?"
        elif any(word in lower for word in ("payment", "cash flow", "liquidity")):
            question = "Which combination of payment timing and commercial terms would give you room to improve the offer?"
        elif any(word in lower for word in ("quality", "ppm", "defect")):
            question = "Could you outline the quality actions and service levels you can commit to in the revised proposal?"
        elif any(word in lower for word in ("material", "energy", "wage", "index", "cost")):
            question = "Could you share the main cost drivers and the portion that applies to this part?"
        else:
            question = "Please review the attached commercial options and let us know which is workable on your side."
        if has_packages:
            opening = (
                "Thank you for your response. We have reviewed the proposal and prepared "
                "alternative commercial terms for your consideration. "
            )
        else:
            opening = "Thank you for your response. We need one point clarified before confirming terms. "
        return "Dear Supplier,\n\n" + opening + question + "\n\nKind regards,\nTaktika Procurement"

    def draft(self, case, reply, evidence, has_packages):
        if not self.model:
            return self.fallback(case, reply, has_packages)
        prompt = (
            "Write a concise procurement email reply (under 90 words) for Hollerau Pumpenwerke. "
            "Acknowledge the supplier's latest message, then ask one useful question or explain a "
            "reciprocal trade. Offer terms have already been selected by code. Do not mention any "
            "number, price, percentage, date, citation, budget, target, or internal calculation. "
            "Return only the email text.\n\n"
            f"Case: {case.get('title', '')}\nSupplier reply: {(reply or {}).get('body', '')[:1600]}\n"
            f"Verified evidence context: {evidence}\nCommercial options attached: {bool(has_packages)}"
        )
        try:
            response = httpx.post(
                f"{self.base}/chat/completions",
                headers={"Authorization": f"Bearer {self.api_key}"},
                json={
                    "model": self.model,
                    "messages": [
                        {"role": "system", "content": "You draft prose only. Never decide the terms."},
                        {"role": "user", "content": prompt},
                    ],
                    "temperature": 0.3,
                },
                timeout=25,
            )
            response.raise_for_status()
            text = response.json()["choices"][0]["message"]["content"].strip()
            if not text or UNSAFE.search(text) or len(text.split()) > 120:
                return self.fallback(case, reply, has_packages)
            return text
        except (httpx.HTTPError, KeyError, TypeError, ValueError):
            return self.fallback(case, reply, has_packages)
"""MCP tools for browsing and exchanging supplier negotiation emails in the Arena."""

from __future__ import annotations

import logging
import os
import threading
from dataclasses import dataclass, field
from typing import Any, Literal

from dotenv import load_dotenv
from mcp.server import MCPServer

from .agent import TaktikaAgent
from .client import ArenaClient
from .play import RemoteTable, load_attachments, live_threads, standing

log = logging.getLogger("taktika.mcp")
server = MCPServer("taktika-arena-email")


@dataclass
class Negotiation:
    case: dict[str, Any]
    threads: dict[str, list[dict[str, Any]]]
    table: RemoteTable
    lock: threading.RLock = field(default_factory=threading.RLock)
    closed_result: dict[str, Any] | None = None


class EmailTools:
    def __init__(self):
        self.client = ArenaClient()
        self.sessions: dict[str, Negotiation] = {}
        self.lock = threading.Lock()

    def get(self, session_id: str) -> Negotiation:
        with self.lock:
            negotiation = self.sessions.get(session_id)
        if negotiation is None:
            raise ValueError("Unknown session: start it with start_negotiation first")
        return negotiation


_tools: EmailTools | None = None
_tools_lock = threading.Lock()


def tools() -> EmailTools:
    global _tools
    with _tools_lock:
        if _tools is None:
            _tools = EmailTools()
    return _tools


def _supplier_thread(service: EmailTools, negotiation: Negotiation, session_id: str,
                     supplier_id: str) -> dict[str, Any]:
    """Refresh cached email events and extract any newly received attachments."""
    thread = service.client.thread(session_id, supplier_id)
    messages = thread.get("messages", [])
    for message in messages:
        load_attachments(negotiation.table, message)
    negotiation.threads[supplier_id] = messages
    return thread


@server.tool()
def list_arena_cases(set_name: Literal["practice", "sandbox", "final"] = "practice") -> list[dict[str, Any]]:
    """List available Arena cases without starting a negotiation."""
    return tools().client.cases(set_name)


@server.tool()
def start_negotiation(case_id: str) -> dict[str, Any]:
    """Open an Arena case and return the suppliers' opening emails and session ID."""
    service = tools()
    opened = service.client.open_session(case_id)
    session_id = opened["session_id"]
    table = RemoteTable(service.client, opened["case"])
    table.session_id = session_id
    threads = opened["threads"]
    for messages in threads.values():
        for message in messages:
            load_attachments(table, message)
    negotiation = Negotiation(opened["case"], threads, table)
    with service.lock:
        service.sessions[session_id] = negotiation
    return {
        "session_id": session_id,
        "case_id": opened["case"].get("case_id", case_id),
        "title": opened["case"].get("title"),
        "suppliers": list(threads),
        "opening_emails": threads,
    }


@server.tool()
def read_supplier_email(session_id: str, supplier_id: str) -> dict[str, Any]:
    """Read a supplier's latest Arena email thread, including extracted attachment text."""
    negotiation = tools().get(session_id)
    if supplier_id not in negotiation.threads:
        raise ValueError("Supplier is not part of this case")
    with negotiation.lock:
        thread = _supplier_thread(tools(), negotiation, session_id, supplier_id)
        messages = negotiation.threads[supplier_id]
        return {
            "supplier_id": supplier_id,
            "status": thread.get("status"),
            "standing_offer_id": thread.get("offer_id"),
            "messages": messages,
        }


@server.tool()
def draft_negotiation_email(session_id: str) -> dict[str, Any]:
    """Ask Taktika to choose the next supplier email or closing action; this does not send it."""
    negotiation = tools().get(session_id)
    with negotiation.lock:
        if negotiation.closed_result:
            return {"status": "closed", "result": negotiation.closed_result}
        if not live_threads(negotiation.threads):
            return {"status": "no_open_threads"}
        decision = TaktikaAgent().decide(negotiation.case, negotiation.threads)
        return decision


@server.tool()
def send_negotiation_email(
    session_id: str,
    supplier_id: str,
    subject: str,
    body: str,
    term_sheets: list[dict[str, Any]] | None = None,
    refs: list[str] | None = None,
) -> dict[str, Any]:
    """Send an email and up to three term sheets to a supplier in the Arena session."""
    negotiation = tools().get(session_id)
    if supplier_id not in negotiation.threads:
        raise ValueError("Supplier is not part of this case")
    term_sheets = term_sheets or []
    refs = refs or []
    if len(term_sheets) > 3:
        raise ValueError("term_sheets must contain at most three term sheets")
    if any(not isinstance(sheet, dict) or not isinstance(sheet.get("terms"), dict)
           for sheet in term_sheets):
        raise ValueError("Each term sheet must be an object with a terms object")
    if len(refs) > 20:
        raise ValueError("refs must contain at most 20 reference IDs")
    if len(subject) > 300 or len(body) > 8000:
        raise ValueError("subject is limited to 300 characters and body to 8000 characters")
    message = {
        "subject": subject,
        "body": body,
        "term_sheets": term_sheets,
        "refs": refs,
    }
    with negotiation.lock:
        _supplier_thread(tools(), negotiation, session_id, supplier_id)
        if supplier_id not in live_threads(negotiation.threads):
            raise ValueError("That supplier thread is already closed")
        reply = tools().client.send_message(session_id, supplier_id, message)
        if "result" in reply:
            negotiation.closed_result = reply["result"]
        else:
            negotiation.threads[supplier_id].extend([
                {**message, "from": "buyer"}, load_attachments(negotiation.table, reply),
            ])
        return {"buyer_email": message, "supplier_reply": reply}


@server.tool()
def close_negotiation(
    session_id: str,
    supplier_id: str,
    action: Literal["accept", "walk_away"],
    term_sheet_id: str = "",
) -> dict[str, Any]:
    """Accept the supplier's current offer or walk away, closing the Arena case."""
    negotiation = tools().get(session_id)
    if supplier_id not in negotiation.threads:
        raise ValueError("Supplier is not part of this case")
    with negotiation.lock:
        service = tools()
        _supplier_thread(service, negotiation, session_id, supplier_id)
        if supplier_id not in live_threads(negotiation.threads):
            raise ValueError("That supplier thread is already closed")
        if action == "accept":
            current_offer_id, _ = standing(negotiation.threads[supplier_id])
            if not term_sheet_id or term_sheet_id != current_offer_id:
                raise ValueError("To accept, supply the current standing term_sheet_id")
            payload = {"action": {"type": "accept", "term_sheet_id": term_sheet_id}}
        else:
            payload = {"action": {"type": "walk_away"}}
        result = service.client.send_message(session_id, supplier_id, payload)
        if "result" in result:
            negotiation.closed_result = result["result"]
            return negotiation.closed_result
        _supplier_thread(service, negotiation, session_id, supplier_id)
        if not live_threads(negotiation.threads):
            negotiation.closed_result = result
            return negotiation.closed_result
        return result


def main():
    load_dotenv()
    logging.basicConfig(level=os.getenv("LOG_LEVEL", "WARNING"))
    tools()
    server.run()


if __name__ == "__main__":
    main()
"""Top-level arena agent that coordinates research, offer planning, and email drafting."""

import os
from pathlib import Path

from .email_writer import EmailWriter
from .research import ProcurementResearch, ResearchStore
from .strategy import OfferPlanner


class TaktikaAgent:
    def __init__(self, package=None, writer=None):
        if package is None:
            root = os.getenv("ARENA_DATA", "data")
            package = ResearchStore(root, os.getenv("ARENA_RELEASE")) if root and Path(root).exists() else None
        self.researcher = ProcurementResearch(package)
        self.planner = OfferPlanner(self.researcher)
        self.writer = writer or EmailWriter()

    def decide(self, case, threads):
        evidence = self.researcher.collect(case)
        return self.planner.decide(case, threads, evidence, self.writer)
"""Deterministic offer planning and close decisions using the arena's published cost model."""

from __future__ import annotations

import math

from .cost_model import OPS, RELATIONSHIP_GOALS, complete_offer, must_haves_ok, total_cost
from .document_reader import supplier_standard_terms
from .play import latest, live_threads, moves_left, standing


class OfferPlanner:
    DISCOUNT = {"leverage": 0.07, "routine": 0.04, "quality_first": 0.015, "stabilise": 0.02, "secure_supply": 0.015}

    def __init__(self, researcher):
        self.researcher = researcher

    def supplier_economics(self, case, supplier_id, standard, research):
        buyer = case["buyer"]
        if buyer.get("category_goal") not in RELATIONSHIP_GOALS or len(case.get("parts", [])) != 1:
            return None
        estimate = next((
            row for row in research["should_cost"]
            if row.get("part_id") == case["parts"][0]
            and row.get("supplier_id") == supplier_id
            and row.get("price") is not None
        ), None)
        if not estimate:
            return None
        card = research["scorecards"].get(supplier_id, {})
        return {
            "full_cost": float(estimate["price"]),
            "interest_rate": float(buyer.get("interest_rate", 0)),
            "usual_rate": float(buyer.get("interest_rate", 0)),
            "ppm": float(card.get("ppm") or standard.get("ppm_commitment") or 0),
            "standard": standard,
        }

    def cost(self, case, terms, standard=None, supplier_id=None, research=None):
        economics = self.supplier_economics(case, supplier_id, standard or {}, research or {}) if research else None
        return total_cost(case, terms, standard, supplier=economics)

    def _choices(self, case, threads, excluded_supplier, research):
        choices = []
        alt = case["buyer"].get("alternative") or {}
        alt_terms = alt.get("terms") or {}
        if alt_terms.get("unit_price") is not None and must_haves_ok(case, alt_terms):
            choices.append((self.cost(case, alt_terms, research=research), "documented alternative"))

        fallback = case["buyer"].get("fallback_unit_price")
        if fallback is not None:
            fallback_terms = complete_offer(case, {"unit_price": float(fallback)})
            if must_haves_ok(case, fallback_terms):
                choices.append((self.cost(case, fallback_terms, research=research), "fallback supply"))

        for sid, events in threads.items():
            if sid == excluded_supplier or sid not in live_threads({sid: events}):
                continue
            sheet_id, terms = standing(events)
            if not sheet_id or terms.get("unit_price") is None:
                continue
            standard = supplier_standard_terms(events)
            if must_haves_ok(case, terms, standard):
                choices.append((self.cost(case, terms, standard, sid, research), f"live quote {sid}"))
        return choices

    def batna(self, case, threads, excluded_supplier, research):
        choices = self._choices(case, threads, excluded_supplier, research)
        return min(choices, default=(math.inf, "no priced alternative"), key=lambda choice: choice[0])

    def target_price(self, case, supplier_id, terms, research):
        buyer = case["buyer"]
        baseline = buyer.get("current_unit_price")
        if baseline is None:
            alternative = buyer.get("alternative") or {}
            baseline = (alternative.get("terms") or {}).get("unit_price")
        if baseline is None:
            case_parts = case.get("parts", [])
            history = [
                row for row in research["purchase_history"]
                if row.get("supplier_id") == supplier_id
                and len(case_parts) == 1 and row.get("part_id") == case_parts[0]
            ]
            history.sort(key=lambda row: row.get("date", ""), reverse=True)
            baseline = history[0].get("price") if history else None
        if baseline is None:
            case_parts = case.get("parts", [])
            history = [
                row for row in research["purchase_history"]
                if len(case_parts) == 1 and row.get("part_id") == case_parts[0]
            ]
            history.sort(key=lambda row: row.get("date", ""), reverse=True)
            baseline = history[0].get("price") if history else None
        if baseline is None:
            baseline = buyer.get("fallback_unit_price") or (terms or {}).get("unit_price") or 1.0

        fair = float(baseline) * (1 + self.researcher.weighted_market_change(research) / 100)
        category = buyer.get("category_goal", "routine")
        target = fair * (1 - self.DISCOUNT.get(category, 0.04))

        # A current, same-part competitor quote is a stronger ceiling than a general index.
        case_parts = case.get("parts", [])
        recent_quotes = [
            row for row in research["quotes"]
            if len(case_parts) == 1 and row.get("part_id") == case_parts[0]
            and row.get("supplier_id") != supplier_id and row.get("price") is not None
        ]
        recent_quotes.sort(key=lambda row: row.get("date", ""), reverse=True)
        if recent_quotes:
            target = min(target, float(recent_quotes[0]["price"]))

        if category in RELATIONSHIP_GOALS and len(case.get("parts", [])) == 1:
            estimate = next((
                row for row in research["should_cost"]
                if row.get("part_id") == case["parts"][0]
                and row.get("supplier_id") == supplier_id and row.get("price") is not None
            ), None)
            if estimate:
                sustainable = max(0.0, min(80.0, float(buyer.get("sustainable_margin_pct") or 0)))
                target = max(target, float(estimate["price"]) / max(0.2, 1 - sustainable / 100))
        return round(max(0.01, target), 2)

    def _optimize_terms(self, case, terms, standard, supplier_id, research):
        options = case.get("term_options", {})
        for _ in range(2):
            moved = False
            for field in case.get("negotiable", []):
                values = options.get(field, [])
                if field == "unit_price" or not values:
                    continue
                musts = [item for item in case["buyer"].get("must_haves", []) if item.get("field") == field]
                candidates = [value for value in values if all(OPS[item["op"]](value, item["value"]) for item in musts)]
                scored = []
                for value in candidates:
                    candidate = complete_offer(case, {**terms, field: value})
                    if must_haves_ok(case, candidate, standard):
                        scored.append((self.cost(case, candidate, standard, supplier_id, research), repr(value), candidate))
                if scored:
                    best = min(scored, key=lambda item: (item[0], item[1]))[2]
                    if terms.get(field) != best.get(field):
                        terms, moved = best, True
            if not moved:
                break
        return complete_offer(case, terms)

    def _max_price(self, case, template, standard, supplier_id, cap, research):
        if not math.isfinite(cap):
            return float(template.get("unit_price") or 0)
        low, high = 0.01, max(10.0, float(template.get("unit_price") or 1) * 8)
        for _ in range(48):
            mid = (low + high) / 2
            candidate = complete_offer(case, {**template, "unit_price": mid})
            if self.cost(case, candidate, standard, supplier_id, research) <= cap + 0.01:
                low = mid
            else:
                high = mid
        return round(low, 2)

    def _within_cap(self, case, terms, standard, sid, cap, research):
        terms = complete_offer(case, terms)
        if self.cost(case, terms, standard, sid, research) <= cap + 0.01:
            return terms
        ceiling = self._max_price(case, terms, standard, sid, cap, research)
        terms["unit_price"] = min(float(terms.get("unit_price") or ceiling), ceiling)
        return complete_offer(case, terms)

    def _packages(self, case, primary, standard, sid, cap, research):
        primary = self._within_cap(case, primary, standard, sid, cap, research)
        packages = []
        if (must_haves_ok(case, primary, standard)
                and self.cost(case, primary, standard, sid, research) <= cap + 0.01):
            packages.append(primary)
        options, allowed = case.get("term_options", {}), set(case.get("negotiable", []))
        musts = case["buyer"].get("must_haves", [])
        uplift = max(0.01, round(float(primary.get("unit_price") or 0) * 0.01, 2))

        def add(candidate):
            candidate = self._within_cap(case, candidate, standard, sid, cap, research)
            if (must_haves_ok(case, candidate, standard)
                    and self.cost(case, candidate, standard, sid, research) <= cap + 0.01
                    and candidate not in packages and len(packages) < 3):
                packages.append(candidate)

        # Show a small set of explicit trades: faster cash or a longer commitment for a price premium.
        for field in ("payment_days", "contract_months"):
            values = options.get(field, [])
            if field not in allowed or not values or len(packages) >= 3:
                continue
            valid = [value for value in values if all(
                OPS[must["op"]](value, must["value"]) for must in musts if must.get("field") == field
            )]
            if not valid:
                continue
            seller_value = min(valid) if field == "payment_days" else max(valid)
            if seller_value == primary.get(field):
                continue
            variant = {**primary, field: seller_value, "unit_price": float(primary.get("unit_price") or 0) + uplift}
            add(variant)
        return packages

    def _state(self, case, sid, events, research):
        sheet_id, offered = standing(events)
        standard = supplier_standard_terms(events)
        terms = complete_offer(case, offered) if offered.get("unit_price") is not None else {}
        valid = bool(terms) and must_haves_ok(case, terms, standard)
        cost = self.cost(case, terms, standard, sid, research) if valid else math.inf
        target = self.target_price(case, sid, terms, research)
        goal_terms = self._optimize_terms(case, complete_offer(case, {**terms, "unit_price": target}), standard, sid, research)
        target_cost = self.cost(case, goal_terms, standard, sid, research)
        return {
            "sheet_id": sheet_id, "terms": terms, "valid": valid, "cost": cost,
            "standard": standard, "target": target, "goal_terms": goal_terms, "target_cost": target_cost,
            "status": latest(events).get("status"), "turn": sum(m.get("from") == "buyer" for m in events),
        }

    def decide(self, case, threads, research, writer):
        live = live_threads(threads)
        if not live:
            raise ValueError("cannot decide after all supplier threads have ended")
        states = {sid: self._state(case, sid, threads[sid], research) for sid in live}
        caps = {
            sid: self.batna(case, {other: events for other, events in threads.items() if other != sid}, sid, research)[0]
            for sid in live
        }

        ready = []
        for sid, state in states.items():
            terminal = state["status"] in {"final_offer", "agreed"} or moves_left(case, threads[sid]) <= 0
            if (state["valid"] and state["sheet_id"] and state["cost"] <= caps[sid] + 0.01
                    and (state["cost"] <= state["target_cost"] + 0.01 or terminal)):
                ready.append((state["cost"], sid, state["sheet_id"]))
        if ready:
            _, sid, offer_id = min(ready)
            return {"supplier_id": sid, "message": {"action": {"type": "accept", "term_sheet_id": offer_id}}}

        writable = [sid for sid in live if moves_left(case, threads[sid]) > 0
                    and states[sid]["status"] not in {"final_offer", "agreed"}]
        if not writable:
            return {"supplier_id": live[0], "message": {"action": {"type": "walk_away"}}}

        # Work the best priced supplier first; if no supplier has quoted yet, pursue the best researched target.
        quoted = [sid for sid in writable if states[sid]["valid"]]
        sid = min(quoted, key=lambda item: (states[item]["cost"], item)) if quoted else min(
            writable, key=lambda item: (states[item]["target_cost"], item)
        )
        state, standard, cap = states[sid], states[sid]["standard"], caps[sid]
        history = [m for m in threads[sid] if m.get("from") == "buyer" and m.get("term_sheets")]
        if history:
            previous = history[-1]["term_sheets"][0]["terms"].get("unit_price", state["target"])
            remaining = max(1, min(5, case.get("round_limit", 10) - 1 - state["turn"]))
            planned_price = float(previous) + (state["target"] - float(previous)) / remaining
            planned_price = min(state["target"], planned_price)
        else:
            # The target already includes the category discount. Keep the opening bid close
            # enough to that evidence-based target to look credible to the supplier.
            planned_price = state["target"] * 0.96
        template = state["terms"] or {}
        primary = self._optimize_terms(
            case, complete_offer(case, {**template, "unit_price": max(0.01, planned_price)}),
            standard, sid, research,
        )
        packages = self._packages(case, primary, standard, sid, cap, research)
        evidence_line, refs = self.researcher.opening_evidence(case, research)
        draft = writer.draft(case, latest(threads[sid]), evidence_line, bool(packages))
        # Verified evidence is inserted by code; the language model is not allowed to alter it.
        body = evidence_line + "\n\n" + draft
        return {
            "supplier_id": sid,
            "message": {
                "subject": f"Re: {case['title']}"[:300],
                "body": body[:8000],
                "term_sheets": [{"terms": package} for package in packages],
                "refs": refs[:20],
            },
        }

