"""Standalone session orchestration for hosted practice, sandbox, and final cases."""

from __future__ import annotations

import functools
import logging
import re
import threading
import time
from concurrent.futures import ThreadPoolExecutor

from .client import ArenaError
from .cost_model import complete_offer, must_haves_ok, total_cost
from .document_reader import extract_text, supplier_standard_terms

log = logging.getLogger("taktika")
FINISHED = {"walked_away", "no_bid"}
RUNNING_SESSION = re.compile(r"one session per case in the final: (\S+)")


class RemoteTable:
    def __init__(self, client, case=None):
        self.client = client
        self.case = case
        self.session_id = None
        self.done = None

    def open(self, case_id):
        if self.session_id:
            return self.resume(self.session_id)
        try:
            response = self.client.open_session(case_id)
        except ArenaError as error:
            match = RUNNING_SESSION.search(str(error.detail)) if error.status == 409 else None
            if not match or self.case is None:
                raise
            return self.resume(match.group(1))
        self.session_id = response["session_id"]
        return response["case"], response["threads"]

    def resume(self, session_id):
        self.session_id = session_id
        state = self.client.session(session_id)
        if state.get("status") == "ended":
            self.done = self.result()
        threads = {
            supplier: self.client.thread(session_id, supplier).get("messages", [])
            for supplier in state.get("threads", {})
        }
        return self.case, threads

    def send(self, supplier, message):
        return self.client.send_message(self.session_id, supplier, message)

    def close(self, supplier, action):
        reply = self.send(supplier, action)
        return reply.get("result", reply)

    def get_attachment(self, attachment_id):
        return self.client.attachment(self.session_id, attachment_id)

    def result(self):
        state = self.client.session(self.session_id)
        return state.get("result") or {
            "deal": False, "end_reason": state.get("end_reason"), "session_id": self.session_id,
        }

    def after_conflict(self, supplier, error):
        state = self.client.session(self.session_id)
        if state.get("status") == "ended":
            return {"result": state.get("result") or {"deal": False, "end_reason": state.get("end_reason")}}
        thread = self.client.thread(self.session_id, supplier)
        timeouts = thread.get("timeouts") or []
        if timeouts:
            latest_timeout = timeouts[-1]
            sheet_id = thread.get("offer_id")
            sheets = ([{"term_sheet_id": sheet_id, "terms": latest_timeout.get("terms", {})}]
                      if sheet_id else [])
            return {
                "from": "arena", "status": "walked_away" if thread.get("closed") else thread.get("status"),
                "term_sheets": sheets, "body": f"({error.detail})", "attachments": [],
            }
        messages = thread.get("messages", [])
        return messages[-1] if messages else {
            "from": "arena", "status": "walked_away", "term_sheets": [],
            "body": f"({error.detail})", "attachments": [],
        }


def latest(messages):
    return next(message for message in reversed(messages) if message.get("from") != "buyer")


def standing(messages):
    sheets = latest(messages).get("term_sheets") or []
    if not sheets:
        return None, {}
    first = sheets[0]
    return first.get("term_sheet_id"), first.get("terms", {})


def live_threads(threads):
    result = []
    for supplier, messages in threads.items():
        if messages and latest(messages).get("status") not in FINISHED:
            result.append(supplier)
    return result


def moves_left(case, messages):
    return case.get("round_limit", 10) - sum(message.get("from") == "buyer" for message in messages)


def load_attachments(table, message):
    for attachment in message.get("attachments") or []:
        identifier = attachment.get("attachment_id")
        if identifier and "text" not in attachment:
            attachment["text"] = extract_text(attachment.get("name", "attachment"),
                                              table.get_attachment(identifier))
    return message


def close_decision(case, threads):
    alternatives = []
    baseline = (case.get("buyer", {}).get("alternative") or {}).get("terms") or {}
    if baseline.get("unit_price") is not None and must_haves_ok(case, baseline):
        alternatives.append(total_cost(case, complete_offer(case, baseline)))
    fallback = case["buyer"].get("fallback_unit_price")
    if fallback is not None:
        fallback_offer = complete_offer(case, {"unit_price": fallback})
        if must_haves_ok(case, fallback_offer):
            alternatives.append(total_cost(case, fallback_offer))
    cap = min(alternatives, default=float("inf"))
    choices = []
    for supplier in live_threads(threads):
        offer_id, terms = standing(threads[supplier])
        standard = supplier_standard_terms(threads[supplier])
        if offer_id and terms.get("unit_price") is not None and must_haves_ok(case, terms, standard):
            amount = total_cost(case, terms, standard)
            if amount <= cap + 0.01:
                choices.append((amount, supplier, offer_id))
    if choices:
        _, supplier, offer_id = min(choices)
        return {"supplier_id": supplier,
                "message": {"action": {"type": "accept", "term_sheet_id": offer_id}}}
    return {"supplier_id": live_threads(threads)[0], "message": {"action": {"type": "walk_away"}}}


def play(table, case_id, agent, deadline=None):
    case, threads = table.open(case_id)
    if table.done:
        return table.done
    for events in threads.values():
        for message in events:
            load_attachments(table, message)
    longest_turn = 0.0
    while live_threads(threads):
        start = time.monotonic()
        cutoff = deadline() if callable(deadline) else deadline
        if cutoff and time.time() > cutoff - max(90.0, longest_turn + 15.0):
            decision = close_decision(case, threads)
        else:
            decision = agent.decide(case, threads)
        supplier, message = decision["supplier_id"], decision["message"]
        if message.get("action"):
            try:
                return table.close(supplier, message)
            except ArenaError as error:
                if error.status != 409:
                    raise
                reply = table.after_conflict(supplier, error)
                if "result" in reply:
                    return reply["result"]
                threads[supplier].append(load_attachments(table, reply))
                continue
        try:
            reply = table.send(supplier, message)
        except ArenaError as error:
            if error.status != 409:
                raise
            reply = table.after_conflict(supplier, error)
            if "result" not in reply:
                threads[supplier].append(load_attachments(table, reply))
                continue
        if "result" in reply:
            return reply["result"]
        threads[supplier].extend([
            {**message, "from": "buyer"}, load_attachments(table, reply),
        ])
        longest_turn = max(longest_turn, time.monotonic() - start)
        log.info("%s: %s", supplier, reply.get("status"))
    return table.result()


def hosted(cases):
    if any("hosted" in case for case in cases):
        return [case for case in cases if case.get("hosted")]
    return cases


def play_all(new_table, case_ids, new_agent, parallel=8):
    quota_spent = threading.Event()

    def run_one(case_id):
        if quota_spent.is_set():
            return case_id, ArenaError(429, "practice quota reached; case not started")
        try:
            return case_id, play(new_table(), case_id, new_agent())
        except ArenaError as error:
            if error.status == 429 and str(error.detail).startswith("practice limit"):
                quota_spent.set()
            log.exception("case %s could not finish", case_id)
            return case_id, error
        except Exception as error:
            log.exception("case %s failed", case_id)
            return case_id, error

    with ThreadPoolExecutor(max_workers=max(1, parallel)) as pool:
        return dict(pool.map(run_one, case_ids))


def play_waves(client, new_agent, waves=5, parallel=10, poll=5.0):
    futures, finished_waves, cutoffs = {}, set(), {}

    def start_case(case, cutoff):
        table = RemoteTable(client, case)
        return play(table, case["case_id"], new_agent(), functools.partial(cutoff.get, case["wave"]))

    with ThreadPoolExecutor(max_workers=max(1, min(parallel, 10))) as pool:
        while len(finished_waves) < waves or any(not future.done() for future in futures.values()):
            try:
                active = client.cases("final")
            except ArenaError as error:
                if error.status != 403:
                    raise
                active = []
            for case in active:
                if not case.get("open"):
                    finished_waves.add(case["wave"])
                    continue
                remaining = case.get("seconds_left")
                if remaining is not None:
                    cutoffs[case["wave"]] = time.time() + remaining
                if case["case_id"] not in futures and remaining:
                    futures[case["case_id"]] = pool.submit(start_case, case, cutoffs)
            time.sleep(poll)
    return {case_id: future.result() for case_id, future in futures.items()}
"""Independent implementation of the arena's published buyer cost equation."""

from __future__ import annotations

import math
import operator
from datetime import date

OPS = {"<=": operator.le, "<": operator.lt, ">=": operator.ge, ">": operator.gt,
       "==": operator.eq, "!=": operator.ne}
RELATIONSHIP_GOALS = {"stabilise", "secure_supply"}


def closing_terms(case, offer, supplier_standard=None):
    buyer = case["buyer"]
    freight = buyer["freight_eur_per_unit"]
    terms = {
        "volume_per_year": buyer["need_per_year"],
        "contract_months": round(12 * buyer["horizon_years"]),
        "payment_days": buyer["reference_payment_days"],
        "lead_time_days": buyer["need_lead_time_days"],
        "incoterm": max(freight, key=freight.get),
    }
    for layer in (supplier_standard or {}, case.get("fixed_terms", {}), offer or {}):
        for field, value in layer.items():
            if value is not None or field not in terms:
                terms[field] = value
    return terms


def _horizon_start(case):
    fixed_date = case.get("fixed_terms", {}).get("effective_date")
    options = case.get("term_options", {}).get("effective_date", [])
    value = fixed_date or (min((item for item in options if item), default=None))
    return date.fromisoformat(value) if value else None


def _years(case, terms):
    months = terms["contract_months"]
    requested = months / 12 if months else 1.0
    return min(requested, case["buyer"]["horizon_years"])


def _units_at_old_price(case, terms, years):
    start = _horizon_start(case)
    effective = terms.get("effective_date")
    if not start or not effective:
        return 0.0
    lag = (date.fromisoformat(effective) - start).days / 365
    return terms["volume_per_year"] * min(max(lag, 0.0), years)


def _supplier_value(case, terms, supplier):
    buyer = case["buyer"]
    standard = {**(supplier.get("standard") or {}), **case.get("fixed_terms", {})}
    freight = buyer["freight_eur_per_unit"]
    if standard.get("payment_days") is None:
        standard["payment_days"] = buyer["reference_payment_days"]
    if standard.get("incoterm") is None:
        standard["incoterm"] = min(freight, key=freight.get)
    standard.setdefault("tooling_eur", 0.0)
    closed = closing_terms(case, terms, standard)
    years = _years(case, closed)
    quantity = closed["volume_per_year"] * years
    if quantity <= 0:
        return float(closed["unit_price"])
    at_old_rate = _units_at_old_price(case, closed, years) / quantity
    finance_rate = supplier["interest_rate"]
    payment_factor = 1 - finance_rate * (closed["payment_days"] - standard["payment_days"]) / 360
    advance_cash_factor = 1 + (finance_rate - supplier.get("usual_rate", finance_rate)) * years / 2
    ppm = supplier.get("ppm", standard.get("ppm_commitment") or 0)
    return (
        closed["unit_price"] * (1 - at_old_rate) * payment_factor
        + at_old_rate * (buyer.get("current_unit_price") or 0.0) * payment_factor
        + freight[closed["incoterm"]] - freight[standard["incoterm"]]
        + ((closed.get("tooling_eur") or 0) - (standard.get("tooling_eur") or 0)) / quantity * advance_cash_factor
        - ppm / 1_000_000 * ((closed.get("chargeback_eur_per_complaint") or 0)
                             - (standard.get("chargeback_eur_per_complaint") or 0))
        + supplier.get("extra", 0.0)
    )


def _relationship_penalty(case, terms, supplier):
    buyer = case["buyer"]
    required_margin = buyer.get("sustainable_margin_pct")
    weight = buyer.get("relationship_eur_per_point")
    if (buyer.get("category_goal") not in RELATIONSHIP_GOALS or not weight or not required_margin
            or not supplier or not supplier.get("full_cost")):
        return 0.0
    sale_value = _supplier_value(case, terms, supplier)
    if sale_value <= 0:
        return 0.0
    margin = (sale_value - supplier["full_cost"]) / sale_value * 100
    shortfall = max(0.0, required_margin - margin)
    smooth_loss = shortfall**2 / 10 if shortfall <= 5 else shortfall - 2.5
    return weight * smooth_loss * _years(case, closing_terms(case, terms, supplier.get("standard")))


def must_haves_ok(case, offer, supplier_standard=None):
    terms = closing_terms(case, offer, supplier_standard)
    for rule in case["buyer"].get("must_haves", []):
        value = terms.get(rule["field"])
        if value is None and rule["op"] not in {"==", "!="}:
            return False
        if not OPS[rule["op"]](value, rule["value"]):
            return False
    return True


def snap(case, field, value):
    options = case.get("term_options", {}).get(field)
    if not options or value in options:
        return value
    if isinstance(value, (int, float)) and all(isinstance(item, (int, float)) for item in options):
        return min(options, key=lambda item: (abs(item - value), item))
    return options[0]


def complete_offer(case, offer):
    buyer = case["buyer"]
    freight = buyer["freight_eur_per_unit"]
    defaults = {
        "volume_per_year": buyer["need_per_year"],
        "contract_months": round(12 * buyer["horizon_years"]),
        "payment_days": buyer["reference_payment_days"],
        "lead_time_days": buyer["need_lead_time_days"],
        "incoterm": min(freight, key=freight.get),
    }
    result = {}
    for field in case["negotiable"]:
        value = (offer or {}).get(field, defaults.get(field))
        if value is None:
            options = case.get("term_options", {}).get(field, [])
            value = options[0] if options else None
        value = snap(case, field, value)
        result[field] = round(value, 2) if field == "unit_price" and value is not None else value
    return result


def cost_parts(case, offer, supplier_standard=None, supplier=None):
    buyer = case["buyer"]
    terms = closing_terms(case, offer, supplier_standard)
    if terms.get("unit_price") is None:
        raise ValueError("a priced term sheet is required")
    years = _years(case, terms)
    committed = terms["volume_per_year"] * years
    need = buyer["need_per_year"]
    covered = min(terms["volume_per_year"], need) * years
    old_price_qty = _units_at_old_price(case, terms, years)
    new_price_qty = committed - old_price_qty
    spend = old_price_qty * (buyer.get("current_unit_price") or terms["unit_price"])
    spend += new_price_qty * terms["unit_price"]

    shortfall_qty = max(0.0, need * buyer["horizon_years"] - covered)
    shortfall = shortfall_qty * buyer["fallback_unit_price"]
    freight = buyer["freight_eur_per_unit"][terms["incoterm"]] * committed
    defect_exposure = buyer.get("cost_per_defect", 0) - min(
        terms.get("chargeback_eur_per_complaint") or 0, buyer.get("cost_per_defect", 0)
    )
    quality = committed * (terms.get("ppm_commitment") or 0) / 1_000_000 * defect_exposure

    index_cost = index_risk = 0.0
    clause = terms.get("index_clause")
    if clause:
        change = buyer.get("index_paths", {}).get(clause["series"], 0.0)
        over_band = max(0.0, abs(change) - clause["deadband_pct"] / 100)
        index_cost = new_price_qty * terms["unit_price"] * clause["material_share"] * over_band
        index_cost *= math.copysign(1, change)
        index_risk = (new_price_qty * terms["unit_price"] * clause["material_share"]
                      * buyer.get("index_risk_pct", 0) / 100)

    components = {
        "purchase": spend,
        "uncovered_need": shortfall,
        "fallback_uncertainty": shortfall * buyer.get("fallback_risk_pct", 0) / 100,
        "cash_timing": spend * buyer["interest_rate"]
        * (buyer["reference_payment_days"] - terms["payment_days"]) / 360,
        "freight": freight,
        "late_delivery": buyer.get("late_cost_per_day", 0)
        * max(0, terms["lead_time_days"] - buyer["need_lead_time_days"]),
        "quality": quality,
        "tooling": terms.get("tooling_eur") or 0.0,
        "index_movement": index_cost,
        "index_variance": index_risk,
        "supplier_health": _relationship_penalty(case, terms, supplier),
    }
    return components


def total_cost(case, offer, supplier_standard=None, supplier=None):
    if closing_terms(case, offer, supplier_standard).get("unit_price") is None:
        return math.inf
    return round(sum(cost_parts(case, offer, supplier_standard, supplier).values()), 2)
"""Find relevant procurement evidence and retain only references the arena can verify."""

from __future__ import annotations

import csv
import json
import sqlite3
from functools import cached_property
from pathlib import Path


class ResearchStore:
    """Read-only access to this project's local facts and SQLite research snapshot."""

    def __init__(self, root, release=None):
        self.root = Path(root).expanduser().resolve()
        facts_file = self.root / "facts.json"
        self.facts = json.loads(facts_file.read_text(encoding="utf-8")) if facts_file.is_file() else {}
        release_path = Path(release).expanduser() if release else self.root / "release-sunday"
        if (release_path / "facts.json").is_file():
            self.facts.update(json.loads((release_path / "facts.json").read_text(encoding="utf-8")))
            self.release = release_path.resolve()
        else:
            self.release = None
        databases = sorted(self.root.rglob("*.sqlite")) + sorted(self.root.rglob("*.db"))
        self.connection = None
        if databases:
            path = databases[0].as_posix()
            self.connection = sqlite3.connect(f"file:{path}?mode=ro", uri=True, check_same_thread=False)
            self.connection.row_factory = sqlite3.Row
            self.connection.execute("PRAGMA query_only=ON")
        if self.connection is None and not self.facts:
            raise FileNotFoundError(f"No research database or fact index found beneath {self.root}")

    def tables(self):
        if not self.connection:
            return {}
        names = [row[0] for row in self.connection.execute(
            "SELECT name FROM sqlite_master WHERE type='table' ORDER BY name"
        )]
        return {
            name: {
                "columns": [row[1] for row in self.connection.execute(f'PRAGMA table_info("{name}")')],
                "rows": self.connection.execute(f'SELECT count(*) FROM "{name}"').fetchone()[0],
            }
            for name in names
        }

    def query(self, statement, params=(), limit=200):
        if not self.connection:
            return []
        head = statement.lstrip().split(None, 1)[0].lower()
        if head not in {"select", "with"}:
            raise ValueError("ResearchStore accepts read-only SELECT queries")
        cursor = self.connection.execute(statement, params)
        return [dict(row) for row in cursor.fetchmany(limit)]

    @cached_property
    def _id_rows(self):
        index = {}
        for table, info in self.tables().items():
            columns = info["columns"]
            if not columns:
                continue
            key = "id" if "id" in columns else columns[0]
            for row in self.connection.execute(f'SELECT * FROM "{table}"'):
                value = row[key]
                if isinstance(value, str) and ":" in value:
                    index[value] = {"table": table, **dict(row)}
        if self.release:
            for file_path in sorted((self.release / "data").glob("*.csv")):
                with file_path.open(encoding="utf-8", newline="") as stream:
                    for row in csv.DictReader(stream):
                        identifier = row.get("id")
                        if identifier:
                            index[identifier] = {"table": file_path.stem, **row, "root": str(self.release)}
        return index

    def lookup(self, identifier):
        return self.facts.get(identifier) or self._id_rows.get(identifier)

    def ids(self, prefix):
        identifiers = set(self.facts)
        if self.connection:
            identifiers.update(self._id_rows)
        return sorted(item for item in identifiers if item.startswith(prefix))

    def document(self, identifier):
        row = self.lookup(identifier)
        if row:
            for field in ("body", "text", "content"):
                if row.get(field):
                    return row[field]
            base = Path(row.get("root", self.root))
            relative = row.get("path") or row.get("file")
            if not relative:
                return json.dumps(row, ensure_ascii=False)
        else:
            base, relative = self.root, identifier
        target = (base / relative).resolve()
        if not target.is_relative_to(base) or not target.is_file():
            raise FileNotFoundError(identifier)
        return target.read_text(encoding="utf-8")


class ProcurementResearch:
    def __init__(self, package):
        self.package = package
        self.tables = set(package.tables()) if package else set()

    def _query(self, table, sql, params=(), limit=30):
        if not self.package or table not in self.tables:
            return []
        try:
            return self.package.query(sql, params, limit=limit)
        except (KeyError, OSError, ValueError):
            return []

    def valid_ref(self, case, ref):
        return bool(
            isinstance(ref, str)
            and (ref in (case.get("facts") or {}) or ref in (case.get("refs") or [])
                 or (self.package and self.package.lookup(ref)))
        )

    def _rows_for_case(self, case):
        parts, suppliers = case.get("parts", []), case.get("suppliers", [])
        if not parts:
            return {}, {}, {}, {}
        units = {
            row["id"]: row.get("price_unit")
            for row in self._query(
                "parts", f"SELECT id, price_unit FROM parts WHERE id IN ({','.join('?' for _ in parts)})", parts
            )
        }
        marks = ",".join("?" for _ in suppliers) or "NULL"
        po_rows, quotes, costs, cards = [], [], [], []
        if suppliers:
            for part in parts:
                unit = units.get(part)
                part_pos = self._query(
                    "po_lines",
                    f"SELECT id, part_id, supplier_id, order_date AS date, price, price_unit, currency, price_note "
                    f"FROM po_lines WHERE part_id = ? AND supplier_id IN ({marks}) ORDER BY order_date DESC LIMIT 30",
                    [part, *suppliers], 30,
                )
                po_rows += [
                    row for row in part_pos
                    if (unit is None or row.get("price_unit") == unit) and row.get("currency", "EUR") == "EUR"
                    and row.get("price_note") != "stale_condition"
                ]
                part_quotes = self._query(
                    "quotes",
                    f"SELECT id, part_id, supplier_id, quote_date AS date, unit_price AS price, price_unit, "
                    f"currency, lead_time_days, incoterm, payment_days, awarded FROM quotes "
                    f"WHERE part_id = ? ORDER BY quote_date DESC LIMIT 40",
                    [part], 40,
                )
                quotes += [
                    row for row in part_quotes
                    if row.get("supplier_id") in suppliers and (unit is None or row.get("price_unit") == unit)
                    and row.get("currency", "EUR") == "EUR"
                ]
                part_costs = self._query(
                    "should_cost",
                    f"SELECT id, part_id, supplier_id, estimate_date AS date, unit_cost AS price, price_unit, "
                    f"confidence_pct, method FROM should_cost WHERE part_id = ? "
                    "ORDER BY estimate_date DESC LIMIT 20",
                    [part], 20,
                )
                costs += [
                    row for row in part_costs
                    if (unit is None or row.get("price_unit") == unit)
                    and (not row.get("supplier_id") or row.get("supplier_id") in suppliers)
                ]
            cards = self._query(
                "scorecards",
                f"SELECT * FROM scorecards WHERE supplier_id IN ({marks}) ORDER BY period_end DESC LIMIT 50",
                suppliers, 50,
            )
        return units, po_rows, quotes, {"costs": costs, "cards": cards}

    @staticmethod
    def _month_index(month):
        try:
            year, value = month[:7].split("-")
            return int(year) * 12 + int(value)
        except (AttributeError, TypeError, ValueError):
            return None

    def _market_moves(self, parts):
        if not self.package or not parts:
            return []
        marks = ",".join("?" for _ in parts)
        drivers = self._query(
            "cost_drivers",
            f"SELECT part_id, series_id, weight FROM cost_drivers WHERE part_id IN ({marks})", parts,
        )
        moves = []
        for driver in drivers:
            series = driver.get("series_id")
            ids = self.package.ids(f"idx:{series}@")
            points = []
            for ref in ids:
                fact = self.package.lookup(ref) or {}
                month = fact.get("month") or ref.rsplit("@", 1)[-1]
                value = fact.get("value")
                ix = self._month_index(month)
                if ix is not None and value is not None:
                    points.append((ix, month, float(value), ref))
            points.sort()
            if len(points) < 2:
                continue
            end = points[-1]
            earlier = [point for point in points[:-1] if 0 < end[0] - point[0] <= 12]
            if not earlier or end[2] == 0:
                continue
            start = earlier[0]
            moves.append({
                "series": series,
                "weight": float(driver.get("weight") or 0),
                "change_pct": (end[2] / start[2] - 1) * 100,
                "start_month": start[1],
                "end_month": end[1],
                "start_ref": start[3],
                "end_ref": end[3],
            })
        # One representative series per code; data can list a driver for more than one part.
        unique = {}
        for move in moves:
            unique[move["series"]] = max(unique.get(move["series"], move), move, key=lambda item: item["weight"])
        return sorted(unique.values(), key=lambda item: item["weight"], reverse=True)

    def collect(self, case):
        units, po_rows, quotes, other = self._rows_for_case(case)
        suppliers = set(case.get("suppliers", []))
        latest_cards = {}
        for row in other["cards"]:
            latest_cards.setdefault(row.get("supplier_id"), row)
        po_rows.sort(key=lambda row: row.get("date", ""), reverse=True)
        quotes.sort(key=lambda row: row.get("date", ""), reverse=True)
        costs = [row for row in other["costs"] if row.get("price") is not None]
        costs.sort(key=lambda row: (row.get("supplier_id") in suppliers, row.get("date", "")), reverse=True)
        moves = self._market_moves(case.get("parts", []))

        refs = []
        for row in po_rows + quotes + costs + list(latest_cards.values()):
            ref = row.get("id")
            if self.valid_ref(case, ref) and ref not in refs:
                refs.append(ref)
        for move in moves:
            for ref in (move["start_ref"], move["end_ref"]):
                if self.valid_ref(case, ref) and ref not in refs:
                    refs.append(ref)
        return {
            "units": units,
            "purchase_history": po_rows,
            "quotes": quotes,
            "should_cost": costs,
            "scorecards": latest_cards,
            "market_moves": moves,
            "refs": refs[:20],
        }

    @staticmethod
    def weighted_market_change(research):
        moves = [move for move in research["market_moves"] if move["weight"] > 0]
        weight = sum(move["weight"] for move in moves)
        if not weight:
            return 0.0
        change = sum(move["weight"] * move["change_pct"] for move in moves)
        if weight > 1:
            change /= weight
        return max(-12.0, min(12.0, change))

    def opening_evidence(self, case, research):
        """A short verifiable claim; keep only IDs the case/package can resolve."""
        # A series change is the clearest argument when both endpoints are available.
        for move in research["market_moves"]:
            if self.valid_ref(case, move["start_ref"]) and self.valid_ref(case, move["end_ref"]):
                sentence = (
                    f"{move['series']} moved {move['change_pct']:+.1f}% from {move['start_month']} "
                    f"to {move['end_month']} ({move['start_ref']}, {move['end_ref']})."
                )
                return sentence, [move["start_ref"], move["end_ref"]]

        by_part = {}
        for row in research["purchase_history"]:
            ref = row.get("id")
            if row.get("part_id") and row.get("price") is not None and self.valid_ref(case, ref):
                by_part.setdefault(row["part_id"], []).append(row)
        for part, rows in by_part.items():
            if len(rows) >= 2:
                first, second = rows[:2]
                sentence = (
                    f"Our matching records for {part} list EUR {float(first['price']):.2f} in {first['id']} "
                    f"and EUR {float(second['price']):.2f} in {second['id']}."
                )
                return sentence, [first["id"], second["id"]]
        return "Thank you for your offer. We have reviewed it against the case requirements.", []
"""Attachment text extraction and quote-term recognition for supplier documents."""

from __future__ import annotations

import io
import re

FIELD_LABELS = {
    "Unit price (EUR)": "unit_price",
    "Payment terms (days net)": "payment_days",
    "Lead time (days)": "lead_time_days",
    "Volume per year (pcs)": "volume_per_year",
    "Contract term (months)": "contract_months",
    "Price valid from": "effective_date",
    "Index clause": "index_clause",
    "Incoterm": "incoterm",
    "Tooling (EUR)": "tooling_eur",
    "Quality commitment (ppm)": "ppm_commitment",
    "Chargeback per complaint (EUR)": "chargeback_eur_per_complaint",
}
HEADINGS = {
    "Offered terms": "stated",
    "Our standard terms": "standard",
    "Terms fixed by your enquiry": "fixed",
    "Agreed terms": "agreed",
}
INDEX_PATTERN = re.compile(r"(\S+), (\d+)% material, deadband ([\d.]+) %, base (\S+)")


def extract_text(filename, content):
    lower_name = filename.lower()
    if lower_name.endswith(".pdf"):
        from pypdf import PdfReader

        return "\n".join(page.extract_text() or "" for page in PdfReader(io.BytesIO(content)).pages)
    if lower_name.endswith(".xlsx"):
        from openpyxl import load_workbook

        workbook = load_workbook(io.BytesIO(content), data_only=False)
        return "\n".join(
            f"[{sheet.title}]\n" + "\n".join(
                " | ".join("" if value is None else str(value) for value in row)
                for row in sheet.iter_rows(values_only=True)
            )
            for sheet in workbook.worksheets
        )
    return content.decode("utf-8", "replace")


def _parse_value(field, raw):
    if field == "index_clause":
        match = INDEX_PATTERN.fullmatch(raw)
        if not match:
            return None
        series, share, band, base = match.groups()
        return {"series": series, "material_share": int(share) / 100,
                "deadband_pct": float(band), "base_month": base}
    if field in {"effective_date", "incoterm"}:
        return raw
    number = float(raw.replace(",", "."))
    return number if field in {"unit_price", "tooling_eur", "chargeback_eur_per_complaint"} else int(number)


def parse_quote(text):
    result, section = {}, None
    for line in text.splitlines():
        line = line.strip()
        for heading, name in HEADINGS.items():
            if line.startswith(heading):
                section = name
                break
        for label, field in FIELD_LABELS.items():
            if section and line.startswith(label + " "):
                try:
                    result.setdefault(section, {})[field] = _parse_value(field, line[len(label):].strip())
                except (ValueError, TypeError):
                    pass
                break
    return result


def supplier_standard_terms(events):
    for message in reversed(events):
        for attachment in message.get("attachments") or []:
            name = attachment.get("name", "")
            if name.startswith("quote") and attachment.get("text"):
                return parse_quote(attachment["text"]).get("standard", {})
    return {}

